// Subtitle translation: the cues of an SRT or WebVTT file go to the local model as keyed batches — the same
// <sN>…</sN> tagging the document translator uses for the runs inside a paragraph — and only the cue text is
// ever sent. Cue numbers, timestamps and the file headers are regenerated by the subtitle writers, so the
// timing of every cue survives untouched. When the model drops some of the markers, the cues that came back
// are kept and only the missing ones are asked for again (up to four rounds); a cue that never comes back
// keeps its source text rather than being lost.

using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;
using Filee.Core.Conversion;
using Filee.Core.Formats;
using Filee.Engines.Subtitles;

namespace Filee.Engines.Translation;

internal static partial class SubtitleTranslator
{
    /// <summary>Cues sent to the model in one request. Cues are short, so a lost batch costs little and recovery is quick.</summary>
    private const int CuesPerBatch = 30;

    /// <summary>How many times the missing cues are asked for again (the answers that did come back are kept).</summary>
    private const int MaxRecoveryRounds = 4;

    /// <summary>
    /// Reads the subtitles of <paramref name="step"/>, translates their cue text with <paramref name="service"/> and
    /// writes the file back in <c>step.To</c> (SRT or WebVTT).
    /// </summary>
    public static async Task<IReadOnlyList<string>> TranslateAsync(
        ConversionStep step, ITranslationService service, string toLang, string fromLang,
        IProgress<double>? progress, CancellationToken cancellationToken)
    {
        var document = SubtitleReader.Read(step.From, await File.ReadAllBytesAsync(step.InputPath, cancellationToken));
        progress?.Report(0.05);

        var cues = document.Cues;
        for (var first = 0; first < cues.Count; first += CuesPerBatch)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var count = Math.Min(CuesPerBatch, cues.Count - first);
            var texts = new List<string>(count);
            for (var i = 0; i < count; i++)
                texts.Add(cues[first + i].Text);

            var translated = await TranslateTextsAsync(texts, toLang, fromLang, service, cancellationToken);
            for (var i = 0; i < count; i++)
            {
                // If the model answered a cue with nothing, or with only broken tags, the cue keeps its
                // original text: one untranslated line is better than a lost one.
                var candidate = SubtitleMarkup.Normalize(translated[i]);
                if (SubtitleMarkup.PlainText(candidate).Length == 0)
                    candidate = cues[first + i].Text;
                cues[first + i] = cues[first + i] with { Text = candidate };
            }

            progress?.Report(0.05 + 0.85 * (first + count) / cues.Count);
        }

        progress?.Report(0.95);
        var output = step.Output.Allocate(FormatRegistry.FindById(step.To)?.PrimaryExtension ?? step.To);
        if (output is null)
            return [];
        await File.WriteAllBytesAsync(output, SubtitleWriter.Write(document, step.To), cancellationToken);
        progress?.Report(1.0);
        return [output];
    }

    /// <summary>
    /// Translates the texts in one keyed request. When the model drops markers, only the cues that are still
    /// missing are asked for again — in one keyed request per round, up to <see cref="MaxRecoveryRounds"/>; the
    /// answers that came back are never re-sent. A text that never comes back keeps its source value.
    /// </summary>
    private static async Task<List<string>> TranslateTextsAsync(
        List<string> texts, string toLang, string fromLang, ITranslationService service, CancellationToken cancellationToken)
    {
        var results = new string?[texts.Count];
        var missing = Enumerable.Range(0, texts.Count).ToHashSet();

        for (var round = 0; round < MaxRecoveryRounds && missing.Count > 0; round++)
        {
            var asked = missing.OrderBy(i => i).ToList();
            var reply = await service.TranslateTextAsync(Keyed(asked, texts), toLang, fromLang, cancellationToken);
            var recovered = 0;
            foreach (Match match in SlotTag().Matches(reply))
            {
                if (!int.TryParse(match.Groups[1].Value, NumberStyles.None, CultureInfo.InvariantCulture, out var index))
                    continue;
                if (missing.Contains(index))
                {
                    results[index] = match.Groups[2].Value.Trim();
                    missing.Remove(index);
                    recovered++;
                }
            }
            // The model ignored the markers (or answered empty): asking again the same way would only repeat
            // the miss, so at most one identical round is wasted.
            if (recovered == 0 && round > 0)
                break;
        }

        return results.Select((t, i) => t ?? texts[i]).ToList();
    }

    /// <summary>Keyed text: <c>&lt;s0&gt;…&lt;/s0&gt;…&lt;sN&gt;…&lt;/sN&gt;</c>, one line per text.</summary>
    private static string Keyed(List<int> indices, List<string> texts)
    {
        var sb = new StringBuilder();
        foreach (var i in indices)
            sb.Append('<').Append('s').Append(i).Append('>').Append(texts[i]).Append("</s").Append(i).Append(">\n");
        return sb.ToString();
    }

    [GeneratedRegex(@"<s(\d+)>(.*?)</s\1>", RegexOptions.Singleline)]
    private static partial Regex SlotTag();
}
